INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `content_en`, `content_bn`, `print_rate_card`, `digital_media_kit`, `is_active`, `created_at`, `updated_at`) VALUES
(5, 'Circulation', 'circulation', '<p class=\"roboto-content\" style=\"font-family: Shurjo, &quot;Siyam Rupali&quot;, Roboto, Arial, Helvetica, monospace; margin: 0px 0px 31.986px; padding: 0px; font-size: 18px; line-height: 1.6; color: rgb(18, 18, 18);\">মূল্যের ভিত্তিতে বাংলাদেশের দৈনিক পত্রিকার বাজার দুই ভাগে বিভক্ত। ১০ টাকা ও এর কম মূল্যের এবং ১০ টাকার ওপরে। দেশের সব পত্রিকার মধ্যে সম্মিলিত বাজারে প্রথম আলোর মার্কেট শেয়ার ৩৮ শতাংশ। ১০ টাকার ওপরের ক্যাটাগরিতে প্রথম আলোর মার্কেট শেয়ার ৬২ শতাংশ।</p><p class=\"roboto-content\" style=\"font-family: Shurjo, &quot;Siyam Rupali&quot;, Roboto, Arial, Helvetica, monospace; margin: 0px 0px 31.986px; padding: 0px; font-size: 18px; line-height: 1.6; color: rgb(18, 18, 18);\">প্রথম আলো দেশের সর্বাধিক পঠিত পত্রিকা। ‘গণমাধ্যম বিষয়ে জাতীয় জনমত জরিপ ২০২৫’ অনুযায়ী, সারা দেশে পত্রিকার পাঠকদের ৫৭ শতাংশের বেশি প্রথম আলো পড়েন। শহরের মতো পল্লি এলাকায়ও সবচেয়ে বেশি পাঠক প্রথম আলোর। ২০২৪ সালের গণ-অভ্যুত্থান-পরবর্তী অন্তর্বর্তী সরকারের গঠিত ‘গণমাধ্যম সংস্কার কমিশন’–এর অনুরোধে বাংলাদেশ পরিসংখ্যান ব্যুরো (বিবিএস) এই জনমত জরিপ চালায়। জরিপ চালানো হয় ২০২৫ সালের ১ থেকে ৭ জানুয়ারি, দেশের ৬৪ জেলায়।</p><p class=\"roboto-content\" style=\"font-family: Shurjo, &quot;Siyam Rupali&quot;, Roboto, Arial, Helvetica, monospace; margin: 0px 0px 31.986px; padding: 0px; font-size: 18px; line-height: 1.6; color: rgb(18, 18, 18);\">২০২১ সালে যুক্তরাজ্যভিত্তিক ক্যান্টার-এমআরবি পরিচালিত জাতীয় গণমাধ্যম জরিপ ২০২১ অনুসারেও প্রথম আলো বাংলাদেশের সর্বোচ্চ পঠিত পত্রিকা।</p><p class=\"roboto-content\" style=\"font-family: Shurjo, &quot;Siyam Rupali&quot;, Roboto, Arial, Helvetica, monospace; margin: 0px 0px 31.986px; padding: 0px; font-size: 18px; line-height: 1.6; color: rgb(18, 18, 18);\">দেশের পাঁচটি আর্থসামাজিক স্তরের সব কটিতেই প্রথম আলোর পাঠকের হার সর্বোচ্চ। আয়ের নিরিখেও সমাজের উচ্চ আয়ের মানুষের মধ্যে প্রথম আলোর জনপ্রিয়তায় কোনো প্রতিদ্বন্দ্বী নেই। প্রথম আলোর সংবাদপত্র বিতরণের নেটওয়ার্ক দেশের মধ্যে সবচেয়ে বড়। প্রায় ৫২৩টি এজেন্ট পয়েন্ট ও প্রায় ১০ হাজার হকার সারা দেশে পাঠকদের মধ্যে প্রথম আলো ছড়িয়ে দিচ্ছেন। সারা দেশের আনাচকানাচে সকাল সকাল পত্রিকাটি পৌঁছে দেওয়ার লক্ষ্যে ঢাকা ও বগুড়া থেকে পত্রিকাটি ছাপা হয়।</p><p class=\"roboto-content\" style=\"font-family: Shurjo, &quot;Siyam Rupali&quot;, Roboto, Arial, Helvetica, monospace; margin: 0px 0px 31.986px; padding: 0px; font-size: 18px; line-height: 1.6; color: rgb(18, 18, 18);\">প্রথাগত খুচরা বিতরণ নেটওয়ার্কের বাইরে প্রথম আলোর করপোরেট সাবস্ক্রিপশনের ব্যবস্থা আছে। বিভিন্ন পেশাজীবী গোষ্ঠী ও প্রতিষ্ঠানকে প্রথম আলো এই সেবা দিয়ে থাকে। বিশেষ উপলক্ষেও এই সেবা দেওয়া হয়।</p><p class=\"roboto-content\" style=\"font-family: Shurjo, &quot;Siyam Rupali&quot;, Roboto, Arial, Helvetica, monospace; margin: 0px 0px 31.986px; padding: 0px; font-size: 18px; line-height: 1.6; color: rgb(18, 18, 18);\">প্রথম আলোর দৈনিক ছাপা পত্রিকার পাশাপাশি কিশোর আলো, বিজ্ঞানচিন্তা ও বর্ণিল-এর মতো বিভিন্ন সাময়িকীও পাঠকেরা নিতে পারেন। এসব বিষয়ে তথ্য কিংবা পুরোনো কোনো সংখ্যা পেতে চাইলে পাঠকেরা এই নম্বরে যোগাযোগ করতে পারেন: <a href=\"tel:09666701070\" style=\"color: rgb(5, 115, 230); text-decoration: none;\">০৯৬৬৬৭০১০৭০</a>।</p><p class=\"roboto-content\" style=\"font-family: Shurjo, &quot;Siyam Rupali&quot;, Roboto, Arial, Helvetica, monospace; margin: 0px 0px 31.986px; padding: 0px; font-size: 18px; line-height: 1.6; color: rgb(18, 18, 18);\">এ ছাড়া পত্রিকা ঠিকমতো না পেলে বা কোনো অভিযোগ করতে হলে যোগাযোগের নম্বর: <a href=\"tel:09666701070\" style=\"color: rgb(5, 115, 230); text-decoration: none;\">০৯৬৬৬৭০১০৭০</a>। শুক্রবার ছাড়া সপ্তাহের অন্যান্য দিন সকাল ১০টা থেকে সন্ধ্যা ৬টা পর্যন্ত এই ফোন উন্মুক্ত।</p>', NULL, NULL, NULL, NULL, 1, '2026-09-21 12:11:54', '2026-09-21 12:11:54');

